package com.hotelmanagement.hms.credit.repository; import com.hotelmanagement.hms.credit.model.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.*; import java.math.*; import java.util.*; public interface CreditLedgerRepository extends JpaRepository<CreditLedgerEntry,UUID>{@Query("select coalesce(sum(e.amount),0) from CreditLedgerEntry e where e.hotelId=:h and e.branchId=:b and e.customerId=:c") BigDecimal balance(UUID h,UUID b,UUID c);}
